css:
/* ONE token set: the app design v53 (35.02-APP-DESIGN/04.ARCHIVE/archhub-directions-v53): dark = index.html :root, light = app.js LIGHT. No other colours or fonts. */
:root{color-scheme:dark;--bg:#0e0e11;--bgDeep:#0a0a0d;--bgPanel:#15151a;--bgSoft:#1c1c23;--bgRaised:#1d1d22;--bgHover:#22222a;--line:#26262e;--lineSoft:#1e1e24;--ink:#ece8e0;--ink2:#9b938a;--ink3:#8b837a;--onFill:#180f08;--accent:#d97757;--accentHi:#e8896a;--accentSoft:#3a2018;--ok:#7ec18e;--warn:#e5b25a;--err:#e6705f;--cyan:#5fb3b3;--blue:#7898d6;--purple:#a98cd6;--f-ui:"Inter",system-ui,sans-serif;--f-mono:"JetBrains Mono",ui-monospace,monospace;--ease:cubic-bezier(.2,0,0,1);--e1:inset 0 1px 0 rgba(255,255,255,.04),0 1px 2px rgba(0,0,0,.4);--e2:inset 0 1px 0 rgba(255,255,255,.05),0 8px 24px rgba(0,0,0,.45);--r-s:6px;--r-m:8px;--r-l:10px}
@media (prefers-color-scheme:light){:root:not([data-theme="dark"]){color-scheme:light;--bg:#f7f4ee;--bgPanel:#fbf9f4;--bgRaised:#fbf9f4;--bgSoft:color-mix(in srgb,#1a1612 4%,#f7f4ee);--bgHover:color-mix(in srgb,#1a1612 7%,#f7f4ee);--line:#e3ddd0;--lineSoft:color-mix(in srgb,#e3ddd0 60%,#f7f4ee);--ink:#1a1612;--ink2:#6b6256;--ink3:#6b6256;--accent:#c96442;--accentHi:#b5573a;--accentSoft:color-mix(in srgb,#c96442 14%,#fbf9f4);--e1:0 1px 2px rgba(26,22,18,.08);--e2:0 8px 24px rgba(26,22,18,.10)}}
:root[data-theme="light"]{color-scheme:light;--bg:#f7f4ee;--bgPanel:#fbf9f4;--bgRaised:#fbf9f4;--bgSoft:color-mix(in srgb,#1a1612 4%,#f7f4ee);--bgHover:color-mix(in srgb,#1a1612 7%,#f7f4ee);--line:#e3ddd0;--lineSoft:color-mix(in srgb,#e3ddd0 60%,#f7f4ee);--ink:#1a1612;--ink2:#6b6256;--ink3:#6b6256;--accent:#c96442;--accentHi:#b5573a;--accentSoft:color-mix(in srgb,#c96442 14%,#fbf9f4);--e1:0 1px 2px rgba(26,22,18,.08);--e2:0 8px 24px rgba(26,22,18,.10)}
:root[data-theme="dark"]{color-scheme:dark}

*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 var(--f-ui);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}img{max-width:100%;display:block}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer;padding:0}
a:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:4px}
code,.mono{font-family:var(--f-mono);font-size:.86em}
.skip{position:absolute;left:16px;top:-60px;z-index:30;background:var(--bgPanel);padding:8px 12px;border-radius:var(--r-m)}.skip:focus{top:8px}

/* ===== shared HEADER (archhub.io, baboom.archhub.io) ===== */
.top{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid var(--lineSoft)}
.top-in{max-width:1200px;margin:0 auto;height:60px;padding:0 24px;display:flex;align-items:center;gap:20px}
.brand{display:flex;align-items:center;gap:10px;font-weight:600;font-size:15px;text-decoration:none;white-space:nowrap}
.crumb{color:var(--ink3);font-weight:400}.crumb a{color:var(--ink);text-decoration:none;font-weight:600}
.nav{display:flex;align-items:center;gap:2px;min-width:0}
.nav>a,.nav .dd>button{display:flex;align-items:center;gap:6px;height:32px;padding:0 10px;border-radius:var(--r-s);text-decoration:none;color:var(--ink2);font-size:14px;white-space:nowrap}
.nav>a:hover,.nav .dd>button:hover{color:var(--ink);background:var(--bgSoft)}
.nav [aria-current="page"]{color:var(--ink);background:var(--bgSoft)}
.dd{position:relative}
.dd-menu{position:absolute;left:0;top:40px;min-width:240px;padding:6px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line);box-shadow:var(--e2);display:none}
.dd.open .dd-menu{display:block}
.dd-menu a{display:block;padding:8px 10px;border-radius:var(--r-s);text-decoration:none;font-size:14px;color:var(--ink2)}.dd-menu a:hover{background:var(--bgSoft);color:var(--ink)}
.dd-menu .lead{color:var(--ink);font-weight:600;border-bottom:1px solid var(--lineSoft);border-radius:var(--r-s) var(--r-s) 0 0;margin-bottom:4px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 18px;border-radius:var(--r-m);font-weight:600;font-size:14px;text-decoration:none;white-space:nowrap;transition:background .15s var(--ease),transform .1s var(--ease)}
.btn:active{transform:translateY(1px)}
.btn-p{background:var(--accent);color:var(--onFill)}.btn-p:hover{background:var(--accentHi)}
.btn-s{box-shadow:inset 0 0 0 1px var(--line);color:var(--ink)}.btn-s:hover{background:var(--bgSoft)}
.top .btn{height:34px;padding:0 14px;font-size:13px;margin-left:auto}
.menu-btn{display:none;height:34px;padding:0 12px;border-radius:var(--r-m);box-shadow:inset 0 0 0 1px var(--line);font-size:13px}
.sheet{display:none;border-top:1px solid var(--lineSoft);padding:8px 16px 16px}
.sheet a{display:block;padding:10px 8px;border-radius:var(--r-s);text-decoration:none;color:var(--ink2)}.sheet a[aria-current="page"]{color:var(--ink);background:var(--bgSoft)}
.sheet .sub{padding-left:24px;font-size:14px}
.top.sheet-open .sheet{display:block}
@media (max-width:899px){.nav{display:none}.menu-btn{display:inline-flex;align-items:center}.top .btn{margin-left:auto}.acct:not([hidden])+.btn{margin-left:0}}

/* ===== page frame ===== */
main{display:block}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
.page{padding:56px 0 88px}
.page[hidden]{display:none}
h1,h2,h3{margin:0;letter-spacing:-.015em;line-height:1.2}
h1{font-size:clamp(30px,4.2vw,48px);font-weight:600;letter-spacing:-.03em}
h2{font-size:clamp(22px,2.4vw,28px);font-weight:600}
h3{font-size:16px;font-weight:600}
p{margin:0}
.lede{font-size:clamp(16px,1.5vw,18px);color:var(--ink2);max-width:60ch;margin-top:16px}
.muted{color:var(--ink2)}.small{font-size:13px}
.sec{margin-top:96px}
.sec-h{max-width:65ch}.sec-h p{color:var(--ink2);margin-top:10px}
.panel{background:var(--bgPanel);border:1px solid var(--line);border-radius:var(--r-l)}

/* home hero */
.hero{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:48px;align-items:center}
.hero .ctas{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
.shot{border-radius:var(--r-l);border:1px solid var(--line);overflow:hidden;background:var(--bgPanel);box-shadow:var(--e2)}
.shot img{width:100%;height:auto}
.cap{font-size:12px;color:var(--ink3);margin-top:10px}
@media (max-width:899px){.hero{grid-template-columns:1fr;gap:32px}}

/* programs: plain rows, no cards */
.hosts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin-top:28px;border-top:1px solid var(--line)}
.hosts div{padding:20px 20px 0 0}.hosts h3{font-size:15px}.hosts p{color:var(--ink2);font-size:14px;margin-top:6px}
@media (max-width:899px){.hosts{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:520px){.hosts{grid-template-columns:1fr}}

/* agents + library split */
.split{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:48px;align-items:center}
.split.rev{grid-template-columns:minmax(0,5fr) minmax(0,7fr)}
@media (max-width:899px){.split,.split.rev{grid-template-columns:1fr;gap:28px}}
.agents{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}
.agents span{padding:6px 12px;border-radius:var(--r-s);background:var(--bgSoft);font-size:14px}

/* BABOOM band */
.bbm{display:grid;grid-template-columns:200px minmax(0,1fr);gap:40px;align-items:center;padding:36px 40px;border-radius:var(--r-l);background:linear-gradient(135deg,var(--accentSoft),var(--bgPanel) 70%);border:1px solid var(--line)}
.bbm img{width:150px;height:auto;justify-self:center}
.bbm-links{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:24px}
.bbm-links a{padding:12px 14px;border-radius:var(--r-m);background:color-mix(in srgb,var(--bg) 55%,transparent);text-decoration:none;font-size:14px;font-weight:500}
.bbm-links a:hover{background:var(--bgSoft)}
.bbm-links small{display:block;color:var(--ink2);font-weight:400;font-size:12px;margin-top:2px}
@media (max-width:899px){.bbm{grid-template-columns:1fr;padding:28px 20px;gap:16px}.bbm img{width:110px}.bbm-links{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:420px){.bbm-links{grid-template-columns:1fr}}

/* release card */
.rel{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center;padding:28px}
.rel dl,.facts{display:grid;grid-template-columns:auto minmax(0,1fr);gap:8px 20px;margin:16px 0 0;font-size:14px}
dt{color:var(--ink3)}dd{margin:0;overflow-wrap:anywhere}
@media (max-width:640px){.rel{grid-template-columns:1fr;padding:20px}}

/* download page */
.dl{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:40px;align-items:start;margin-top:36px}
.dl .panel{padding:28px}
.dl-steps{counter-reset:s;list-style:none;padding:0;margin:20px 0 0}
.dl-steps li{position:relative;padding:0 0 22px 44px}
.dl-steps li::before{counter-increment:s;content:counter(s);position:absolute;left:0;top:0;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--bgSoft);font:600 13px var(--f-mono)}
.dl-steps p{color:var(--ink2);font-size:14px;margin-top:4px}
.hash{font:12px var(--f-mono);color:var(--ink2);overflow-wrap:anywhere}
@media (max-width:899px){.dl{grid-template-columns:1fr}}

/* docs */
.docs{display:grid;grid-template-columns:240px minmax(0,1fr);gap:48px;margin-top:8px}
.side-nav{position:sticky;top:84px;align-self:start;font-size:14px}
.side-nav h4{margin:20px 0 6px;font-size:12px;font-weight:600;color:var(--ink3)}
.side-nav h4:first-child{margin-top:0}
.side-nav a{display:block;padding:5px 10px;border-radius:var(--r-s);text-decoration:none;color:var(--ink2)}
.side-nav a:hover{color:var(--ink)}.side-nav a[aria-current="page"]{color:var(--ink);background:var(--bgSoft)}
.doc-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:28px}
.doc-list a{display:block;padding:18px 20px;text-decoration:none;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.doc-list a:hover{border-color:var(--ink3)}
.doc-list a p{color:var(--ink2);font-size:14px;margin-top:4px}
.doc-list a.wide{grid-column:1/-1;background:linear-gradient(135deg,var(--accentSoft),var(--bgPanel) 60%)}
.tut{columns:2;column-gap:32px;margin-top:20px;padding:0;list-style:none}
.tut li{break-inside:avoid;padding:10px 0;border-bottom:1px solid var(--lineSoft)}
.tut a{text-decoration:none}.tut a:hover{color:var(--accent)}
@media (max-width:899px){.docs{grid-template-columns:1fr;gap:24px}.side-nav{position:static;display:none}.doc-list{grid-template-columns:1fr}.tut{columns:1}}
/* the shared ARTICLE (site and app Docs read the same) */
.article{max-width:72ch}
.article h1{font-size:clamp(28px,3.4vw,38px)}
.article h2{font-size:20px;margin:40px 0 10px}
.article p,.article li{color:var(--ink2);line-height:1.75}
.article p+p{margin-top:12px}
.article ol,.article ul{padding-left:22px}.article li{margin-bottom:8px}
.article code{background:var(--bgSoft);padding:1px 6px;border-radius:4px;color:var(--ink)}
.use{display:flex;gap:16px;align-items:flex-start;margin:28px 0;padding:18px 20px;border-radius:var(--r-l);background:var(--accentSoft);border:1px solid color-mix(in srgb,var(--accent) 35%,transparent)}
.use b{display:block;color:var(--ink)}.use p{color:var(--ink2);margin:4px 0 0;font-size:14px}
.crumbs{font-size:13px;color:var(--ink3);margin-bottom:14px}.crumbs a{color:var(--ink2);text-decoration:none}

/* community */
.com{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;margin-top:36px}
.com a.big{display:flex;flex-direction:column;justify-content:space-between;min-height:200px;padding:28px;border-radius:var(--r-l);text-decoration:none;border:1px solid var(--line);background:var(--bgPanel)}
.com a.big:first-child{background:linear-gradient(160deg,var(--accentSoft),var(--bgPanel) 65%)}
.com a.big:hover{border-color:var(--ink3)}
.com a.big p{color:var(--ink2);margin-top:8px;max-width:44ch}
.com .go{font-size:13px;color:var(--ink2);margin-top:24px}
@media (max-width:760px){.com{grid-template-columns:1fr}}
.stats{display:flex;flex-wrap:wrap;gap:40px;margin-top:28px}
.stats div b{display:block;font-size:28px;font-weight:600;letter-spacing:-.02em}.stats div span{color:var(--ink2);font-size:13px}
.people{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;margin-top:20px}
.person{display:flex;gap:14px;align-items:center;padding:16px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line);text-decoration:none}
.person:hover{border-color:var(--ink3)}
.av{width:44px;height:44px;border-radius:50%;background:var(--bgHover);flex:none;object-fit:cover}
.av.lg{width:96px;height:96px}
.prof{display:grid;grid-template-columns:auto minmax(0,1fr);gap:28px;align-items:center}
.empty{margin-top:20px;padding:32px;border-radius:var(--r-l);border:1px dashed var(--line);text-align:center;color:var(--ink2)}
.empty b{display:block;color:var(--ink);margin-bottom:6px}
@media (max-width:560px){.prof{grid-template-columns:1fr;gap:16px}}

/* cloud */
.cl{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:40px;margin-top:40px;align-items:start}
.cl ol{padding-left:22px;color:var(--ink2)}.cl li{margin-bottom:10px}
.state{display:grid;grid-template-columns:auto 1fr;gap:10px 14px;font-size:14px}
.tag{font:500 12px var(--f-mono);padding:2px 8px;border-radius:999px;white-space:nowrap;align-self:start}
.tag.on{color:var(--ok);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--ok) 45%,transparent)}
.tag.off{color:var(--ink3);box-shadow:inset 0 0 0 1px var(--line)}
.priv{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);margin-top:28px;border-radius:var(--r-l);overflow:hidden;border:1px solid var(--line)}
.priv>div{padding:24px}.priv>div+div{border-left:1px solid var(--line);background:var(--bgPanel)}
.priv ul{margin:12px 0 0;padding-left:18px;color:var(--ink2);font-size:14px}.priv li{margin-bottom:6px}
@media (max-width:899px){.cl{grid-template-columns:1fr}}
@media (max-width:640px){.priv{grid-template-columns:1fr}.priv>div+div{border-left:0;border-top:1px solid var(--line)}}

/* changelog */
.log{display:grid;grid-template-columns:200px minmax(0,1fr);gap:8px 40px;margin-top:40px}
.log time{font:13px var(--f-mono);color:var(--ink3);padding-top:4px}
.log .entry{padding-bottom:36px;border-bottom:1px solid var(--lineSoft);margin-bottom:28px}
.log .entry:last-child{border-bottom:0}
.log ul{margin:8px 0 0;padding-left:20px;color:var(--ink2)}.log li{margin-bottom:8px}
.log .gap{color:var(--warn)}
@media (max-width:760px){.log{grid-template-columns:1fr;gap:4px}.log .entry{margin-bottom:20px}}

/* baboom entry */
.redir{display:flex;gap:14px;align-items:center;padding:14px 18px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line);margin-top:24px;font-size:14px;color:var(--ink2)}
.redir code{color:var(--ink)}
.demo{margin-top:40px;border-radius:var(--r-l);overflow:hidden;border:1px solid var(--line)}
.demo .top{position:static}
.demo-body{padding:32px 24px;display:grid;grid-template-columns:minmax(0,1fr) 140px;gap:24px;align-items:center;background:var(--bg)}
.demo-body img{width:110px;justify-self:center}
@media (max-width:640px){.demo-body{grid-template-columns:1fr}.demo-body img{display:none}}

/* ===== shared FOOTER: mark + four grouped columns + bar ===== */
.foot{margin-top:24px;background:var(--bgPanel);border-top:1px solid var(--line)}
.foot-in{max-width:1200px;margin:0 auto;padding:56px 24px 40px;display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px 32px}
.foot .brand{margin-bottom:12px}
.foot-tag{color:var(--ink2);font-size:14px;max-width:30ch}
.foot-cta{display:flex;gap:10px;margin-top:20px;flex-wrap:wrap}
.foot-cta .btn{height:36px;padding:0 14px;font-size:13px}
.foot h4{margin:0 0 14px;font-size:13px;font-weight:600;color:var(--ink)}
.foot ul{list-style:none;margin:0;padding:0}.foot li{margin-bottom:10px}
.foot ul a{color:var(--ink2);text-decoration:none;font-size:14px;transition:color .15s var(--ease)}
.foot ul a:hover{color:var(--accent)}
.foot ul a .ext{opacity:.55;margin-left:4px;font-size:12px}
.foot-bar-wrap{border-top:1px solid var(--line)}
.foot-bar{max-width:1200px;margin:0 auto;padding:18px 24px 28px;display:flex;justify-content:space-between;align-items:center;gap:12px 24px;flex-wrap:wrap;font-size:13px;color:var(--ink3)}
.foot-bar nav{display:flex;gap:6px 20px;flex-wrap:wrap}
.foot-bar a{color:var(--ink3);text-decoration:none}.foot-bar a:hover{color:var(--ink)}
.theme{display:inline-flex;padding:3px;border-radius:var(--r-m);background:var(--bgSoft)}
.theme button{padding:4px 10px;border-radius:var(--r-s);font-size:12px;color:var(--ink2)}
.theme button:hover{color:var(--ink)}
.theme button[aria-pressed="true"]{background:var(--bg);color:var(--ink);box-shadow:var(--e1)}
@media (max-width:1180px){.foot-in{grid-template-columns:repeat(4,minmax(0,1fr))}.foot-in>div:first-child{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 32px;align-items:start}.foot-in>div:first-child .foot-up{margin-top:0;grid-row:1/4;grid-column:2}}
@media (max-width:700px){.foot-in>div:first-child{display:block}.foot-in>div:first-child .foot-up{margin-top:20px}}
@media (max-width:700px){.foot-in{grid-template-columns:repeat(2,minmax(0,1fr));gap:32px 20px}}

/* ===== account slot (shown only to a signed-in founder; nothing for the public) ===== */
.acct{position:relative;margin-left:auto}
.acct:not([hidden])+.btn{margin-left:0}
.acct-btn{display:flex;align-items:center;gap:6px;height:34px;padding:0 6px 0 3px;border-radius:999px;box-shadow:inset 0 0 0 1px var(--line)}
.acct-btn:hover,.acct.open .acct-btn{background:var(--bgSoft)}
.av.sm{width:28px;height:28px}
.dd-menu.right{left:auto;right:0}
.acct.open .dd-menu{display:block}
.who{padding:8px 10px 10px;border-bottom:1px solid var(--lineSoft);margin-bottom:4px;font-size:13px;color:var(--ink2)}.who b{display:block;color:var(--ink);font-size:14px}
.dd-menu button{display:block;width:100%;text-align:left;padding:8px 10px;border-radius:var(--r-s);font-size:14px;color:var(--ink2)}.dd-menu button:hover{background:var(--bgSoft);color:var(--ink)}
.priv-tag{font:500 11px var(--f-mono);color:var(--accent);margin-left:auto}

/* ===== loading + unavailable states (release card, GitHub numbers) ===== */
.sk{display:inline-block;min-width:7ch;height:1em;border-radius:4px;background:linear-gradient(90deg,var(--bgSoft),var(--bgHover),var(--bgSoft));background-size:200% 100%;animation:sk 1.2s linear infinite;vertical-align:-2px;color:transparent}
@keyframes sk{to{background-position:-200% 0}}
.unav{color:var(--ink3);font-size:13px}
.state-note{display:flex;gap:8px;align-items:center;margin-top:14px;font-size:13px;color:var(--ink3)}
.state-note[hidden]{display:none}

/* ===== ELEMENT STATES sheet (/_states: design board, not a public page) ===== */
.st-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));gap:16px;margin-top:28px}
.st{padding:20px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.st h3{font-size:14px;margin-bottom:4px}.st>p{font-size:13px;color:var(--ink2);margin-bottom:16px}
.st-row{display:grid;grid-template-columns:96px minmax(0,1fr);gap:10px 14px;align-items:center;font-size:12px}
