/* ===== motion: one product feel, values from the app design owner's Interaction rule (35.02 surface-model-001): fast 120 / medium 180 / slow 240; ease for moves, ease-out for arrivals ===== */
:root{--d-fast:120ms;--d-menu:180ms;--d-page:240ms;--ease-out:cubic-bezier(.16,1,.3,1)}
.page:not([hidden]){animation:pageIn var(--d-page) var(--ease-out) both}
@keyframes pageIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.dd-menu,.pidx-p{display:block!important;visibility:hidden;opacity:0;transform:translateY(-4px) scale(.98);transform-origin:top left;transition:opacity var(--d-menu) var(--ease),transform var(--d-menu) var(--ease),visibility 0s linear var(--d-menu)}
.dd-menu.right{transform-origin:top right}.pidx-p{transform-origin:bottom left;transform:translateY(4px) scale(.98)}
.dd.open .dd-menu,.acct.open .dd-menu,.pidx.open .pidx-p,.st .dd-menu{visibility:visible;opacity:1;transform:none;transition-delay:0s}
.sheet{display:block!important;max-height:0;overflow:hidden;padding-top:0;padding-bottom:0;border-top-color:transparent;transition:max-height var(--d-page) var(--ease),padding var(--d-page) var(--ease)}
.top.sheet-open .sheet{max-height:80vh;overflow:auto;padding-top:8px;padding-bottom:16px;border-top-color:var(--lineSoft)}
@media (min-width:900px){.sheet{display:none!important}}
.nav>a,.nav .dd>button,.auth-in,.sub-in a,.dd-menu a,.side-nav a{transition:background var(--d-fast) var(--ease),color var(--d-fast) var(--ease)}
@media (prefers-reduced-motion:reduce){.page:not([hidden]){animation:none}.dd-menu,.pidx-p,.sheet{transition:none}}

