.bstart li>b{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--accentSoft);color:var(--accent);font:600 14px var(--f-mono)}
.bstart p{color:var(--ink2);font-size:14px;margin:6px 0 14px}.bstart li>div{display:flex;flex-direction:column;flex:1}.bstart .btn{margin-top:auto;align-self:flex-start}
