.smap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;margin-top:28px}
.results{list-style:none;padding:0;margin:8px 0 0;max-width:760px}.results li{padding:14px 0;border-bottom:1px solid var(--lineSoft);display:grid;gap:2px}
.results small{color:var(--ink3);font-size:13px}.r-k{font:500 11px var(--f-mono);color:var(--accent)}
.sub-in button.ask-l{flex:none;height:30px;padding:0 10px;border-radius:var(--r-s);font-size:13px;margin-left:auto;display:flex;gap:6px;align-items:center}
.sub-in button.ask-l:hover{background:var(--bgSoft)}
@media (max-width:1008px){.bstart,.libs,.smap{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:560px){.bstart,.smap{grid-template-columns:1fr}.libs{grid-template-columns:1fr}.lib.big{grid-column:auto;grid-row:auto}}

/* ===== BABOOM companion (every page) ===== */
.bbmc{position:fixed;right:16px;bottom:16px;z-index:45;display:flex;flex-direction:column;align-items:flex-end;gap:10px;pointer-events:none}
.bbmc>*{pointer-events:auto}
/* one BABOOM: the app's sprite (bbm-sprite.png, 80x87 frames), shadow, float and state glow; spec 003 §5 */
.bbm-btn{position:relative;width:80px;height:100px;border-radius:12px;animation:bbmIn var(--d-page) var(--ease-out) both;transition:transform var(--d-fast) var(--ease);filter:drop-shadow(0 5px 6px rgba(0,0,0,.35))}
.bbm-btn:hover{transform:translateY(-2px)}.bbm-btn:active{transform:translateY(0) scale(.97)}
.bbm-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.spr{display:block;width:80px;height:87px;background:url(site-assets/bbm-sprite.png) 0 0/640px 609px no-repeat}
.bbm-btn .spr{position:absolute;left:0;bottom:0}
.spr[data-pose=idle]{animation:bp7 2.1s steps(7,jump-none) infinite}
.spr[data-pose=wave]{background-position-y:-87px;animation:bp4 560ms steps(4,jump-none) 2}
.spr[data-pose=think]{background-position-y:-174px;animation:bp8 1100ms steps(8,jump-none) infinite}
.spr[data-pose=present]{background-position-y:-261px;animation:bp6 780ms steps(6,jump-none) 1 both}
@keyframes bp4{from{background-position-x:0}to{background-position-x:-240px}}
@keyframes bp6{from{background-position-x:0}to{background-position-x:-400px}}
@keyframes bp7{from{background-position-x:0}to{background-position-x:-480px}}
@keyframes bp8{from{background-position-x:0}to{background-position-x:-560px}}
.bbm-btn::after{content:"";position:absolute;left:50%;bottom:-2px;width:46px;height:9px;margin-left:-23px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.35),transparent);transition:background var(--d-menu) var(--ease)}
.bbm-btn[data-state=listening]::after{background:radial-gradient(closest-side,color-mix(in srgb,var(--cyan) 75%,transparent),transparent)}
.bbm-btn[data-state=working]::after{background:radial-gradient(closest-side,color-mix(in srgb,var(--accent) 70%,transparent),transparent);animation:bbglow 1.4s var(--ease) infinite}
.bbm-btn:not(:active){animation:bbmIn var(--d-page) var(--ease-out) both,bbfloat 3.6s ease-in-out var(--d-page) infinite}
@keyframes bbglow{50%{opacity:.45;transform:scaleX(.8)}}
@keyframes bbfloat{50%{translate:0 -3px}}
.bbm-ph .spr{width:80px;height:87px;scale:.4;margin:-26px -24px;flex:none}
.bbm-btn .live-dot{position:absolute;top:8px;right:10px}
.bbm-btn[aria-expanded="true"] .live-dot{display:none}
@keyframes bbmIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.bbm-bubble{max-width:250px;padding:10px 32px 10px 14px;border-radius:14px 14px 4px 14px;background:var(--bgPanel);border:1px solid var(--line);box-shadow:var(--e2);font-size:13px;position:relative;animation:bubIn var(--d-menu) var(--ease-out) both;margin-right:28px}
.bbm-bubble[hidden]{display:none}
.bbm-bubble button{position:absolute;right:6px;top:6px;width:22px;height:22px;border-radius:6px;color:var(--ink3)}.bbm-bubble button:hover{background:var(--bgSoft);color:var(--ink)}
@keyframes bubIn{from{opacity:0;transform:translateY(4px) scale(.98)}to{opacity:1;transform:none}}
.bbm-panel{width:min(380px,calc(100vw - 32px));max-height:min(560px,calc(100dvh - 140px));display:flex;flex-direction:column;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line);box-shadow:var(--e2);overflow:hidden;animation:panIn var(--d-menu) var(--ease-out) both;transform-origin:bottom right}
.bbm-panel[hidden]{display:none}
@keyframes panIn{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:none}}
.bbm-ph{display:flex;gap:10px;align-items:center;padding:12px 12px 12px 14px;border-bottom:1px solid var(--line);background:var(--bgPanel)}
.bbm-ph b{display:block;font-size:14px}.bbm-ph span{font-size:12px;color:var(--ink2)}
.bbm-ph button{margin-left:auto;width:30px;height:30px;border-radius:var(--r-s);font-size:18px;color:var(--ink2)}.bbm-ph button:hover{background:var(--bgSoft);color:var(--ink)}
.bbm-log{padding:14px;overflow:auto;display:flex;flex-direction:column;gap:8px;flex:1;min-height:160px}
.bbm-msg{padding:9px 12px;border-radius:12px 12px 12px 4px;background:var(--bg);border:1px solid var(--lineSoft);font-size:14px;align-self:flex-start;max-width:92%}
.bbm-msg.me{align-self:flex-end;border-radius:12px 12px 4px 12px;background:var(--accentSoft);border-color:transparent}
.bbm-msg.busy{color:var(--ink2);display:flex;gap:8px;align-items:center}
.bbm-note{font-size:12px;color:var(--ink2);padding:8px 10px;border-radius:var(--r-m);background:var(--bgSoft)}
.bbm-in{display:flex;gap:8px;padding:10px;border-top:1px solid var(--line)}
.bbm-in input{flex:1;min-width:0;height:38px;padding:0 12px;border-radius:var(--r-m);border:1px solid var(--line);background:var(--bg);color:var(--ink);font:inherit}
.bbm-in input:focus{outline:2px solid var(--accent);outline-offset:1px;border-color:transparent}
.bbm-in .btn{height:38px}
@media (max-width:520px){.bbmc{right:10px;bottom:10px}.bbm-btn{scale:.8;transform-origin:100% 100%}.bbm-bubble{max-width:200px}}
@media (prefers-reduced-motion:reduce){.bbm-btn,.bbm-btn::after,.bbm-bubble,.bbm-panel,.spr{animation:none!important}}
.ask-note{display:grid;grid-template-columns:120px minmax(0,1fr);gap:32px;align-items:center}.ask-note>img{width:96px;height:auto;justify-self:center}
@media (max-width:640px){.ask-note{grid-template-columns:1fr;gap:12px}.ask-note>img{width:64px;justify-self:start}}

/* community */
.cm-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap}
.cm-act{display:flex;gap:12px;flex-wrap:wrap}
.cm-tabs{display:flex;gap:2px;margin-top:32px;border-bottom:1px solid var(--line);overflow-x:auto;scrollbar-width:none}
.cm-tabs button{flex:none;height:42px;padding:0 14px;font-size:14px;color:var(--ink2);border-bottom:2px solid transparent;margin-bottom:-1px;transition:color var(--d-fast) var(--ease),border-color var(--d-fast) var(--ease)}
.cm-tabs button:hover{color:var(--ink)}.cm-tabs button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--accent);font-weight:600}
.cm-panel[hidden]{display:none}.cm-panel{animation:pageIn var(--d-menu) var(--ease-out) both}
.cm-h{font-size:18px;margin:32px 0 0}
.packs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:14px}
.pack{display:flex;flex-direction:column;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line);overflow:hidden;transition:border-color var(--d-fast) var(--ease)}
.pack:hover{border-color:var(--ink3)}
.pack-pv{aspect-ratio:16/9;background:#0e0e11;overflow:hidden}.pack-pv img{width:100%;height:100%;object-fit:cover;object-position:left top}
.pack-b{display:flex;flex-direction:column;gap:6px;padding:16px;flex:1}
.pack-t{display:flex;justify-content:space-between;align-items:center}.pack-k{font-size:12px;color:var(--ink3)}
.pack-b p{color:var(--ink2);font-size:14px}
.pack-m{display:flex;gap:12px;font-size:12px;color:var(--ink3);margin-top:2px}.warn-t{color:var(--warn)}
.pack-a{display:flex;align-items:center;gap:12px;margin-top:auto;padding-top:10px;flex-wrap:wrap}
.qa-list{margin-top:20px}
.news{list-style:none;padding:0;margin:20px 0 0;max-width:820px}
.news li{display:grid;grid-template-columns:120px minmax(0,1fr);gap:20px;padding:18px 0;border-bottom:1px solid var(--lineSoft)}
.news time{font:13px var(--f-mono);color:var(--ink3);padding-top:2px}.news p{color:var(--ink2);font-size:14px;margin:4px 0 6px}.news a{font-size:13px}
.share-gate{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;max-width:760px;margin-top:28px;padding:16px 20px;border-radius:var(--r-l);background:var(--accentSoft)}
.chk{display:flex;gap:10px;align-items:center;font-weight:400!important}.chk input{width:18px;height:18px}
@media (max-width:1008px){.packs{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.packs{grid-template-columns:1fr}.news li{grid-template-columns:1fr;gap:4px}}

/* pricing */
.pr-hero{max-width:760px}.pr-hero .ctas{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}
.pr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-top:22px;border-top:1px solid var(--line)}
.pr-grid>div{padding:20px 24px 20px 0;border-bottom:1px solid var(--lineSoft)}.pr-grid p{color:var(--ink2);font-size:14px;margin-top:6px}
.plans3 .tag{display:inline-block;margin-top:12px}
@media (max-width:760px){.pr-grid{grid-template-columns:1fr}}

/* small-screen fixes */
.fld input,.fld select,.fld textarea{width:100%;min-width:0}
.filt select{max-width:100%}
.tbl-wrap{max-width:100%;position:relative}.tbl th{position:relative}
@media (max-width:520px){.si-box{padding:20px 16px}.filt input{flex-basis:100%;max-width:none}}

/* download depth */
.found{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:24px}
.found>div{padding:22px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.found ul.plain{margin-top:8px}.found li{font-size:14px;color:var(--ink2)}
.faq{margin-top:20px;max-width:820px;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{list-style:none;cursor:pointer;padding:16px 32px 16px 0;font-weight:600;position:relative}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"";position:absolute;right:6px;top:22px;width:8px;height:8px;border-right:1.5px solid var(--ink2);border-bottom:1.5px solid var(--ink2);transform:rotate(45deg);transition:transform var(--d-menu) var(--ease)}
.faq details[open] summary::after{transform:rotate(-135deg);top:26px}
.faq summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}
.faq p{color:var(--ink2);padding:0 0 16px;max-width:65ch}
@media (max-width:760px){.found{grid-template-columns:1fr}}

/* starter chains (real steps from starters.py on main) */
.job{gap:8px!important}
.chain{list-style:none;margin:6px 0 2px;padding:0;display:flex;flex-wrap:wrap;gap:4px 0;align-items:center;font-size:12px}
.chain li{padding:3px 8px;border-radius:6px;background:var(--bg);border:1px solid var(--lineSoft);color:var(--ink2);white-space:nowrap}
.chain li+li::before{content:"";display:inline-block;width:10px;height:1px;background:var(--line);vertical-align:middle;margin:0 0 0 -19px;position:relative;left:-0px}
.chain li+li{margin-left:14px;position:relative}
.chain li+li::after{content:"";position:absolute;left:-14px;top:50%;width:14px;height:1px;background:var(--ink3);opacity:.6}
.chain li+li::before{display:none}
.chain li.ag{border-style:dashed}
.chain li.gate{background:var(--accentSoft);border-color:color-mix(in srgb,var(--accent) 40%,transparent);color:var(--ink);font-weight:600}
.job-stop{font-size:13px;color:var(--ink2);margin-top:auto;padding-top:6px;border-top:1px solid var(--lineSoft)}
.cm-jobs{margin-top:14px}

/* arrival motion (ease-out arrivals, 240 ms; off under reduced motion) */
.rv{opacity:0;transform:translateY(10px);transition:opacity var(--d-page) var(--ease-out),transform var(--d-page) var(--ease-out)}
.rv.in{opacity:1;transform:none}
.chain li{transition:background var(--d-menu) var(--ease),border-color var(--d-menu) var(--ease),color var(--d-menu) var(--ease)}
.chain li.lit{background:var(--accentSoft);border-color:var(--accent);color:var(--ink)}
.shot{transition:transform var(--d-page) var(--ease-out),box-shadow var(--d-page) var(--ease-out)}.shot:hover{transform:translateY(-3px)}
[hidden].fam,[hidden].job,tr[hidden],li[hidden]{display:none!important}
@media (prefers-reduced-motion:reduce){.rv{opacity:1;transform:none;transition:none}}

/* features */
.ft{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-top:40px}
.ft-big{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:40px;align-items:center;padding:8px 0 24px}
.ft-big.rev{grid-template-columns:minmax(0,5fr) minmax(0,7fr)}.ft-big.rev .shot{order:2}
.ft-txt p{color:var(--ink2);margin-top:10px;max-width:46ch}
.ft-c{padding:22px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.ft-c p{color:var(--ink2);font-size:14px;margin-top:8px}.ft-c.tint{background:linear-gradient(160deg,var(--accentSoft),var(--bgPanel) 70%)}
@media (max-width:1008px){.ft{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:760px){.ft{grid-template-columns:1fr}.ft-big,.ft-big.rev{grid-template-columns:1fr;gap:20px}.ft-big.rev .shot{order:0}}
/* pricing */
.pr{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:36px;max-width:880px}
.pr-c{display:flex;flex-direction:column;padding:28px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.pr-c.on{border-color:color-mix(in srgb,var(--accent) 55%,var(--line));box-shadow:var(--e2)}
.pr-c ul{margin:16px 0 24px;padding-left:18px;color:var(--ink2);font-size:14px;flex:1}.pr-c li{margin-bottom:8px}.pr-c .btn{align-self:flex-start}
@media (max-width:700px){.pr{grid-template-columns:1fr}}
.sec-facts{max-width:820px;gap:14px 28px;font-size:15px}.sec-facts dd{color:var(--ink2)}
/* sign in */
.si{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:40px;align-items:start}
.si-box{margin-top:32px;padding:28px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.si-box.web{margin-top:0;display:flex;flex-direction:column}.si-box.web .btn{align-self:flex-start}
@media (max-width:899px){.si{grid-template-columns:1fr;gap:20px}}

/* ===== prototype page index (design aid, not part of the site) ===== */
.pidx{position:fixed;left:16px;bottom:16px;z-index:40;font-size:13px}
.pidx>button{display:flex;align-items:center;gap:8px;height:36px;padding:0 14px;border-radius:999px;background:var(--ink);color:var(--bg);font-weight:600;box-shadow:var(--e2)}
.pidx-p{position:absolute;left:0;bottom:46px;width:min(560px,calc(100vw - 32px));max-height:min(70vh,640px);overflow:auto;padding:16px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line);box-shadow:var(--e2);display:none}
.pidx.open .pidx-p{display:block}
.pidx-p h5{margin:12px 0 6px;font-size:11px;font-weight:600;color:var(--ink3);text-transform:uppercase;letter-spacing:.06em}.pidx-p h5:first-child{margin-top:0}
.pidx-g{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:2px 8px}
.pidx-g a{padding:5px 8px;border-radius:var(--r-s);text-decoration:none;color:var(--ink2)}.pidx-g a:hover{background:var(--bgSoft);color:var(--ink)}.pidx-g a[aria-current="page"]{background:var(--accentSoft);color:var(--ink)}
.pidx-note{margin-top:12px;color:var(--ink3);font-size:12px}

/* cockpit door */
.door{max-width:560px;margin-top:32px;padding:28px;border-radius:var(--r-l);background:var(--bgPanel);border:1px solid var(--line)}
.door .facts{margin-top:18px}

@media (max-width:520px){.wrap,.top-in,.foot-in,.foot-bar{padding-left:16px;padding-right:16px}.page{padding:36px 0 64px}.sec{margin-top:64px}}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}

/* one identity (18 Nov): placeholder avatar, account page in the site shell, same tokens as the app */
.av.ph{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--userAv,#d8c5a8);color:var(--onUserAv,#5a4a2a);font:600 11px var(--f-ui)}
.pidx{display:none!important}
.acch{display:flex;align-items:center;gap:14px;margin-bottom:22px}.acch .av{display:inline-grid;place-items:center;border-radius:50%;background:var(--userAv,#d8c5a8);color:var(--onUserAv,#5a4a2a);font-weight:600}.acch .btn{margin-left:auto}.av.big{width:44px;height:44px;font-size:16px}
.accg{display:grid;grid-template-columns:200px minmax(0,1fr);gap:24px;align-items:start}@media(max-width:760px){.accg{grid-template-columns:1fr}.accn{display:none}}
.accn{position:sticky;top:80px;display:grid;gap:2px}.accn a{padding:7px 10px;border-radius:6px;color:var(--ink2);text-decoration:none}.accn a:hover{background:var(--bgSoft);color:var(--ink)}
.accs{border:1px solid var(--line);border-radius:10px;background:var(--bgPanel);padding:4px 16px 8px;margin-bottom:16px;scroll-margin-top:80px}.accs h2{font-size:15px;margin:12px 0 4px}
.accr{display:grid;grid-template-columns:minmax(140px,1fr) minmax(0,1.3fr);gap:12px;align-items:center;min-height:44px;border-top:1px solid var(--lineSoft);font-size:13.5px}.accr:first-of-type{border-top:0}.accr>span{color:var(--ink2)}
.accr input{height:32px;padding:0 10px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--ink);font:inherit}.accr.ro .rov{color:var(--ink);line-height:1.6;padding:6px 0}
.soonchip{display:inline-block;margin:0 4px;padding:0 7px;height:18px;line-height:18px;border-radius:999px;border:1px dashed var(--line);font:600 10.5px var(--f-ui);color:var(--ink3);vertical-align:1px}
